-- World chests (game objects, opened with a cast). Keys are negative object IDs so they never clash with
-- item IDs; every spawn variant of a chest shares one entry. Rows as in Data.lua:
-- { itemID, percent chance per opening, quality, name, stackMin, stackMax, tier }
-- tier: AH price ranked within THIS chest (see make_chests.py), so the same item can differ per chest.
local _, ns = ...
ns.ChestObjects = {}  -- [game object entry ID] = chest key
ns.ChestNames = {}    -- [chest name] = chest key
local function add(key, objs, c)
    c.world, c.category, c.money = true, "World chests", 0
    ns.Containers[key] = c
    ns.ChestNames[c.name] = key
    for _, o in ipairs(objs) do ns.ChestObjects[o] = key end
end
